toolScript:
let bpm = 100;
        let isRunning = false;
        let beatCount = 0;
        let tapTimes = [];
        let beatTimes = [];
        let intervalId = null;
        let audioContext = null;

        function selectBPM(newBpm) {
            bpm = newBpm;
            document.querySelectorAll('.bpm-option').forEach(btn => {
                btn.classList.remove('selected');
                if (parseInt(btn.dataset.bpm) === bpm) {
                    btn.classList.add('selected');
                }
            });
        }

        function initAudio() {
            if (!audioContext) {
                audioContext = new (window.AudioContext || window.webkitAudioContext)();
            }
        }

        function playBeep() {
            if (!audioContext) return;
            const oscillator = audioContext.createOscillator();
            const gainNode = audioContext.createGain();
            oscillator.connect(gainNode);
            gainNode.connect(audioContext.destination);
            oscillator.frequency.value = 800;
            gainNode.gain.value = 0.3;
            oscillator.start();
            gainNode.gain.exponentialRampToValueAtTime(0.01, audioContext.currentTime + 0.1);
            oscillator.stop(audioContext.currentTime + 0.1);
        }

        function startTest() {
            initAudio();
            isRunning = true;
            beatCount = 0;
            tapTimes = [];
            beatTimes = [];
            updateDisplay();

            const interval = 60000 / bpm;
            playBeep();
            beatTimes.push(Date.now());

            intervalId = setInterval(() => {
                beatCount++;
                playBeep();
                beatTimes.push(Date.now());
                updateBeatIndicators();
                updateDisplay();
            }, interval);

            document.getElementById('startBtn').disabled = true;
            document.getElementById('startBtn').textContent = 'Running...';
        }

        function stopTest() {
            isRunning = false;
            if (intervalId) {
                clearInterval(intervalId);
                intervalId = null;
            }
            document.getElementById('startBtn').disabled = false;
            document.getElementById('startBtn').textContent = 'Start Test';
        }

        function resetTest() {
            stopTest();
            beatCount = 0;
            tapTimes = [];
            beatTimes = [];
            document.getElementById('beatCounter').textContent = '0';
            document.getElementById('avgDeviation').textContent = '0ms';
            document.getElementById('syncScore').textContent = '0%';
            document.getElementById('consistency').textContent = '0%';
            document.getElementById('timingDots').innerHTML = '';
        }

        function handleTap() {
            if (!isRunning) return;
            const tapTime = Date.now();
            tapTimes.push(tapTime);
            analyzeTap(tapTime);
        }

        function analyzeTap(tapTime) {
            const interval = 60000 / bpm;
            const lastBeat = beatTimes[beatTimes.length - 1];
            const deviation = tapTime - lastBeat;

            if (tapTimes.length > 1) {
                const tapInterval = tapTime - tapTimes[tapTimes.length - 2];
                const expectedInterval = interval;
                const consistency = Math.max(0, 100 - Math.abs(tapInterval - expectedInterval) / expectedInterval * 100);

                document.getElementById('consistency').textContent = Math.round(consistency) + '%';
            }

            const absDeviation = Math.abs(deviation);
            document.getElementById('avgDeviation').textContent = Math.round(absDeviation) + 'ms';

            const perfectWindow = interval * 0.15;
            const syncScore = Math.max(0, 100 - (absDeviation / perfectWindow) * 100);
            document.getElementById('syncScore').textContent = Math.round(syncScore) + '%';

            addTimingDot(deviation, perfectWindow);
        }

        function addTimingDot(deviation, perfectWindow) {
            const container = document.getElementById('timingDots');
            const dot = document.createElement('div');
            dot.className = 'timeline-marker w-3 h-3 rounded-full flex-shrink-0';

            if (Math.abs(deviation) <= perfectWindow) {
                dot.classList.add('bg-green-500');
            } else if (Math.abs(deviation) <= perfectWindow * 2) {
                dot.classList.add('bg-yellow-500');
            } else {
                dot.classList.add('bg-red-500');
            }

            container.appendChild(dot);
            if (container.children.length > 20) {
                container.removeChild(container.firstChild);
            }
        }

        function updateBeatIndicators() {
            const dots = ['beatDot1', 'beatDot2', 'beatDot3', 'beatDot4'];
            dots.forEach((id, index) => {
                const dot = document.getElementById(id);
                dot.classList.remove('beat-pulse');
                dot.style.backgroundColor = '#f9a8d4';
            });

            const currentBeat = (beatCount % 4);
            const currentDotId = dots[currentBeat];
            const dot = document.getElementById(currentDotId);
            dot.classList.add('beat-pulse');
            dot.style.backgroundColor = '#ec4899';
        }

        function updateDisplay() {
            document.getElementById('beatCounter').textContent = beatCount;
        }

        document.addEventListener('keydown', (e) => {
            if (e.code === 'Space') {
                e.preventDefault();
                handleTap();
            }
        });

        function toggleFaq(btn) {
            const answer = btn.nextElementSibling;
            const icon = btn.querySelector('.faq-icon');
            answer.classList.toggle('open');
            icon.classList.toggle('rotate-180');
        }
